steps.script:
(() => {
  // A. 과거 대화 소급 표기 + 헤더 우측 정렬 (기본 폭).
  //    배포본이 서빙하는 실 app.js 가 실 대화 데이터(step.created_at)로 렌더한 결과만 본다 —
  //    함수를 옮겨 심지 않는다(사본을 재는 것은 배포 검증이 아니다).
  try { localStorage.setItem('web.stepSidePanel.width', '340'); } catch (e) {}
  const btn = document.querySelector('.bubble-steps-btn');
  if (!btn) throw new Error('PB0008 FAIL: 단계 보기 버튼 없음 (대상 대화에 meta.steps 부재)');
  btn.click();
  const panel = document.getElementById('stepSidePanel');
  const hdrs = [...document.querySelectorAll('.step-side-panel-item-header')];
  const times = [...document.querySelectorAll('.step-side-panel-time')];
  if (!hdrs.length) throw new Error('PB0008 FAIL: 단계 항목 0');
  // 시각 표기 형식 — 1번째는 기준점이라 시각만, 이후는 '시각 · +간격 · 누적 경과'.
  const CLOCK = /^\d{2}:\d{2}:\d{2}$/;
  const FULL = /^\d{2}:\d{2}:\d{2} · \+(?:\d+(?:\.\d)?초|\d+분 \d+초) · 누적 (?:\d+(?:\.\d)?초|\d+분 \d+초)$/;
  const texts = times.map((t) => t.textContent.trim());
  const badFmt = texts.filter((s, i) => (i === 0 ? !CLOCK.test(s) : !FULL.test(s)));
  // 기하 — 우측 정렬(헤더 content 우변과 시간 우변 일치) · 넘침 0 · 형제 요소와 겹침 0.
  const geo = hdrs.map((h) => {
    const t = h.querySelector('.step-side-panel-time');
    if (!t) return null;
    const hr = h.getBoundingClientRect(), tr = t.getBoundingClientRect();
    const padR = parseFloat(getComputedStyle(h).paddingRight) || 0;
    const sib = [...h.children].filter((c) => c !== t).map((c) => c.getBoundingClientRect());
    return {
      gapRight: +(hr.right - padR - tr.right).toFixed(2),
      overflow: +(tr.right - hr.right).toFixed(2),
      overlap: sib.some((o) => !(o.right <= tr.left || o.left >= tr.right || o.bottom <= tr.top || o.top >= tr.bottom)),
    };
  }).filter(Boolean);
  const cs = getComputedStyle(times[0]);
  const csH = getComputedStyle(hdrs[0]);
  const m = {
    panelW: Math.round(panel.getBoundingClientRect().width),
    steps: hdrs.length,
    timed: times.length,
    badFmt: badFmt.length,
    firstIsClockOnly: CLOCK.test(texts[0] || ''),
    maxGapRight: Math.max(...geo.map((g) => g.gapRight)),
    minGapRight: Math.min(...geo.map((g) => g.gapRight)),
    maxOverflow: Math.max(...geo.map((g) => g.overflow)),
    anyOverlap: geo.some((g) => g.overlap),
    whiteSpace: cs.whiteSpace,
    tabularNums: cs.fontVariantNumeric,
    flexShrink: cs.flexShrink,
    marginLeftResolved: parseFloat(cs.marginLeft) > 0,
    headerFlexWrap: csH.flexWrap,
    sample: texts.slice(0, 4),
  };
  // 판정을 사람 눈에 맡기지 않는다 — 어긋나면 이 step 이 실패한다.
  const bad = [];
  if (m.timed !== m.steps) bad.push('timed=' + m.timed + '/' + m.steps);
  if (m.badFmt !== 0) bad.push('badFmt=' + JSON.stringify(badFmt));
  if (!m.firstIsClockOnly) bad.push('firstIsClockOnly=false (' + texts[0] + ')');
  if (m.maxGapRight !== 0 || m.minGapRight !== 0) bad.push('gapRight=' + m.minGapRight + '..' + m.maxGapRight);
  if (m.maxOverflow > 0) bad.push('overflow=' + m.maxOverflow);
  if (m.anyOverlap) bad.push('overlap=true');
  if (m.whiteSpace !== 'nowrap') bad.push('whiteSpace=' + m.whiteSpace);
  if (m.tabularNums !== 'tabular-nums') bad.push('tabularNums=' + m.tabularNums);
  if (m.flexShrink !== '0') bad.push('flexShrink=' + m.flexShrink);
  if (!m.marginLeftResolved) bad.push('marginLeft(auto) 미해소');
  if (m.headerFlexWrap !== 'wrap') bad.push('headerFlexWrap=' + m.headerFlexWrap);
  if (bad.length) throw new Error('PB0008 ASSERT FAIL A ' + JSON.stringify(bad));
  return JSON.stringify(m);
})()

(() => {
  // 확대 캡처 — 패널이 뷰포트의 일부(300~340px)라 전체화면 캡처만으로는 10.5px 시간 표기가
  // 판독 불가다(§16.6 '판독 가능한 캡처' 요구). 라이브 패널 DOM 을 **그대로 복제**해 2.2배로
  // 확대한 오버레이를 얹는다 — 재렌더가 아니라 복제이므로 보이는 픽셀은 라이브 것과 동일하다.
  const mk = (label) => {
    document.querySelectorAll('#pb-steptiming-zoom').forEach((n) => n.remove());
    const panel = document.getElementById('stepSidePanel');
    const host = document.createElement('div');
    host.id = 'pb-steptiming-zoom';
    host.setAttribute('data-marker', 'steptiming-pb0008-ef1f438a');
    host.style.cssText = 'position:fixed;inset:0;z-index:2147483647;background:#fff;overflow:auto';
    const hd = document.createElement('div');
    hd.style.cssText = 'font:600 13px/1.5 system-ui;padding:10px 20px;border-bottom:1px solid #e5e9f0;color:#26251e';
    hd.textContent = 'PB-0008 · 실행 단계 패널 시각/간격/누적 표기 (라이브 패널 DOM 복제 2.2× 확대) · ' + label + ' · marker=steptiming-pb0008-ef1f438a';
    host.appendChild(hd);
    const stage = document.createElement('div');
    stage.style.cssText = 'transform:scale(2.2);transform-origin:top left;width:' + Math.round(panel.getBoundingClientRect().width) + 'px';
    const clone = panel.cloneNode(true);
    clone.removeAttribute('id');
    clone.style.cssText = 'position:static;width:100%;height:auto;max-height:none;box-shadow:none;border:1px solid #e5e9f0';
    const body = clone.querySelector('#stepSidePanelBody');
    if (body) { body.style.maxHeight = 'none'; body.style.overflow = 'visible'; }
    stage.appendChild(clone);
    host.appendChild(stage);
    document.body.appendChild(host);
    return host.querySelectorAll('.step-side-panel-time').length;
  };
  const n = mk('폭 340px (기본)');
  if (!n) throw new Error('PB0008 FAIL: 확대 복제에 시간 표기 0');
  window.__pbZoom = mk;
  return JSON.stringify({ zoomedTimes: n });
})()

(() => {
  // B. 최소 폭(300px)에서 겹침 없음 — 리사이저를 **실제로 끌어** 최소 폭까지 좁힌다
  //    (스타일 직접 주입이 아니라 운영 경로: mousedown → mousemove → mouseup + localStorage 영속).
  document.querySelectorAll('#pb-steptiming-zoom').forEach((n) => n.remove());
  const h = document.getElementById('stepSidePanelResizer');
  const panel = document.getElementById('stepSidePanel');
  if (!h) throw new Error('PB0008 FAIL: 리사이저 없음');
  const r = h.getBoundingClientRect();
  h.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, clientX: r.left + 2, clientY: r.top + 40 }));
  // 최소 폭보다 더 좁게 끌어 클램프(STEP_PANEL_MIN_W=300)가 걸리는지까지 본다.
  document.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, cancelable: true, clientX: window.innerWidth - 180, clientY: r.top + 40 }));
  document.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true }));
  const hdrs = [...document.querySelectorAll('.step-side-panel-item-header')];
  const geo = hdrs.map((x) => {
    const t = x.querySelector('.step-side-panel-time');
    const xr = x.getBoundingClientRect(), tr = t.getBoundingClientRect();
    const padR = parseFloat(getComputedStyle(x).paddingRight) || 0;
    const sib = [...x.children].filter((c) => c !== t).map((c) => c.getBoundingClientRect());
    return {
      gapRight: +(xr.right - padR - tr.right).toFixed(2),
      overflow: +(tr.right - xr.right).toFixed(2),
      overlap: sib.some((o) => !(o.right <= tr.left || o.left >= tr.right || o.bottom <= tr.top || o.top >= tr.bottom)),
    };
  });
  const bodyEl = document.getElementById('stepSidePanelBody');
  const m = {
    panelW: Math.round(panel.getBoundingClientRect().width),
    savedW: (() => { try { return localStorage.getItem('web.stepSidePanel.width'); } catch (e) { return null; } })(),
    anyOverlap: geo.some((g) => g.overlap),
    maxOverflow: Math.max(...geo.map((g) => g.overflow)),
    gapRights: [...new Set(geo.map((g) => g.gapRight))],
    bodyHScroll: bodyEl.scrollWidth - bodyEl.clientWidth,
  };
  const bad = [];
  if (m.panelW !== 300) bad.push('panelW=' + m.panelW + ' (min clamp 300 미적용)');
  if (m.savedW !== '300') bad.push('savedW=' + m.savedW);
  if (m.anyOverlap) bad.push('overlap=true');
  if (m.maxOverflow > 0) bad.push('overflow=' + m.maxOverflow);
  if (m.gapRights.length !== 1 || m.gapRights[0] !== 0) bad.push('gapRights=' + JSON.stringify(m.gapRights));
  if (m.bodyHScroll > 0) bad.push('bodyHScroll=' + m.bodyHScroll);
  if (bad.length) throw new Error('PB0008 ASSERT FAIL B ' + JSON.stringify(bad));
  return JSON.stringify(m);
})()

(() => {
  // C. 줄바꿈 폴백 — 300px 에서 실 데이터는 아직 한 줄에 들어간다. 그러나 요청의 계약은
  //    "기존 텍스트 위치와 충돌 없이" 이므로, 폭이 모자란 최악의 경우에 **겹치는 대신 줄바꿈**
  //    하는지를 확인해야 한다(flex-wrap). 도구 배지를 길게 만들어 그 경계를 강제한다.
  document.querySelectorAll('#pb-steptiming-zoom').forEach((n) => n.remove());
  const hdr = [...document.querySelectorAll('.step-side-panel-item-header')].find((x) => x.querySelector('.step-tool-badge'));
  if (!hdr) throw new Error('PB0008 FAIL: 도구 배지가 있는 단계 없음');
  const badge = hdr.querySelector('.step-tool-badge');
  const t = hdr.querySelector('.step-side-panel-time');
  const before = { top: +(t.getBoundingClientRect().top - hdr.getBoundingClientRect().top).toFixed(1), h: +hdr.getBoundingClientRect().height.toFixed(1) };
  const orig = badge.textContent;
  badge.textContent = '테이블 구조 조회 · 스키마 메타데이터';
  const hr = hdr.getBoundingClientRect(), tr = t.getBoundingClientRect(), br = badge.getBoundingClientRect();
  const m = {
    beforeTop: before.top, beforeH: before.h,
    afterTop: +(tr.top - hr.top).toFixed(1), afterH: +hr.height.toFixed(1),
    badgeTop: +(br.top - hr.top).toFixed(1),
    overlap: !(br.right <= tr.left || br.left >= tr.right || br.bottom <= tr.top || br.top >= tr.bottom),
    overflow: +(tr.right - hr.right).toFixed(2),
  };
  window.__pbRestore = () => { badge.textContent = orig; };
  const bad = [];
  if (m.beforeTop > 2) bad.push('평상시에도 줄바꿈(beforeTop=' + m.beforeTop + ')');
  if (m.afterTop <= 2) bad.push('폭 부족에도 줄바꿈 안 함(afterTop=' + m.afterTop + ')');
  if (m.overlap) bad.push('overlap=true (겹침 발생 — 계약 위반)');
  if (m.overflow > 0) bad.push('overflow=' + m.overflow);
  if (bad.length) throw new Error('PB0008 ASSERT FAIL C ' + JSON.stringify(bad));
  return JSON.stringify(m);
})()

(() => {
  const n = window.__pbZoom('폭 300px · 폭 부족 시 줄바꿈(겹침 0)');
  if (!n) throw new Error('PB0008 FAIL: 확대 복제 실패');
  // 줄바꿈이 일어난 단계(도구 배지가 긴 4번)가 캡처 안에 **보이도록** 스크롤한다 —
  // 계약이 지켜졌다는 주장을 화면 밖에 두면 캡처가 근거가 되지 못한다(§16.6).
  const host = document.getElementById('pb-steptiming-zoom');
  const clone = host.querySelector('.step-side-panel-item:nth-of-type(4)') || host.querySelectorAll('.step-side-panel-item')[3];
  if (clone) host.scrollTop = Math.max(0, clone.getBoundingClientRect().top - host.getBoundingClientRect().top + host.scrollTop - 60);
  return JSON.stringify({ zoomedTimes: n, scrollTop: Math.round(host.scrollTop) });
})()
